"""Readability scores."""
from __future__ import annotations

import re

from textstats.tokenize import sentences, words

_VOWELS = re.compile(r"[aeiouy]+")


def syllable_count(word: str) -> int:
    w = word.lower()
    n = len(_VOWELS.findall(w))
    if w.endswith("e") and not w.endswith(("le", "ee")) and n > 1:
        n -= 1
    return max(1, n)


def sentence_count(text: str) -> int:
    return len(sentences(text))


def flesch_reading_ease(text: str) -> float:
    ws = words(text)
    if not ws:
        return 0.0
    s = max(1, sentence_count(text))
    syl = sum(syllable_count(w) for w in ws)
    return round(206.835 - 1.015 * len(ws) / s - 84.6 * syl / len(ws), 2)

